  "fixed_code": "from django.http import JsonResponse\nfrom django.views.decorators.http import require_GET\nfrom django.http import HttpRequest\n\nfrom .models import Article\n\n\n@require_GET\ndef articles_by_author(request: HttpRequest) -> JsonResponse:\n    \"\"\"Retrieve a list of articles for a given author, limited by a specified count.\"\"\"\n    author = request.GET.get(\"author\", \"\")\n    if not author:\n        return JsonResponse({\"error\": \"Author parameter is required\"}, status=400)\n\n    limit = min(int(request.GET.get(\"limit\", 10)), 50)\n    \n    articles = Article.objects.filter(author=author).order_by('-published')[:limit].values('id', 'title', 'published')\n    \n    payload = [\n        {\"id\": a['id'], \"title\": a['title'], \"published\": a['published'].isoformat()}\n        for a in articles\n    ]\n    return JsonResponse({\"articles\": payload})"
